8818: /**
8819:  * @brief CPU 最近邻回退（仅 EPIC 不可用/超时时走；与 EPIC 同一套语义）。
8820:  *
8821:  * @details 逆向映射：src = R(-θ)·(dst - center) + center，θ 顺时针。
8822:  *          坐标按**像素中心**算（像素 i 覆盖 [i,i+1)，中心 i+0.5）—— 这与
8823:  *          EPIC 的 pivot 语义一致（HAL 的 `EPIC_GetRotatedArea` 用 `w - pivot`），
8824:  *          90° 的整数倍能把 200×200 网格**逐像素**映射回自己，不产生 1px 漂移。
8825:  *          采样越界时保留 face 原像素（= 上一帧的纸色），与 EPIC 的
8826:  *          "背景 = 目的层本身"一致。
8827:  */
8828: static void helm_ring_face_cpu(int32_t angle)
8829: {
8830:     const int a = helm_ring_norm((int)angle);
8831:     const int32_t cs = lv_trigo_cos((int16_t)a);
8832:     const int32_t sn = lv_trigo_sin((int16_t)a);
8833:     const int32_t cx = HELM_RING_ART_W / 2;
8834:     const int32_t cy = HELM_RING_ART_H / 2;
8835:     int32_t y;
8836: 
8837:     if (s_ring_art == NULL || s_ring_face == NULL) {
8838:         return;
8839:     }
8840: 
8841:     for (y = 0; y < HELM_RING_ART_H; y++) {
8842:         uint16_t *drow = s_ring_face + (size_t)y * HELM_RING_ART_W;
8843:         const int32_t hy = 2 * y + 1 - 2 * cy;   /* 2 × (dy，以像素中心算) */
8844:         int32_t x;
8845: 
8846:         for (x = 0; x < HELM_RING_ART_W; x++) {
8847:             const int32_t hx = 2 * x + 1 - 2 * cx;
8848:             const int64_t nx = (int64_t)cs * hx + (int64_t)sn * hy;
8849:             const int64_t ny = -(int64_t)sn * hx + (int64_t)cs * hy;
8850:             const int32_t sx = helm_ring_floor16(nx) + cx;
8851:             const int32_t sy = helm_ring_floor16(ny) + cy;
8852: 
8853:             if (sx >= 0 && sy >= 0 && sx < HELM_RING_ART_W &&
8854:                 sy < HELM_RING_ART_H) {
8855:                 drow[x] = s_ring_art[(size_t)sy * HELM_RING_ART_W + (size_t)sx];
8856:             }
8857:         }
8858:     }
8859: }
