9209: /** @brief 转子（扇区 ±26° + 指针 T）在页面坐标下的包围盒（含 4px 余量）。 */
9210: static void helm_ring_rotor_bbox(int angle, lv_area_t * a)
9211: {
9212:     const int r_out = HELM_RING_D / 2;       /* 100 */
9213:     const int r_in = r_out - 16;             /* 84：扇区内沿 */
9214:     const int edges[2] = { angle - 26, angle + 26 };
9215:     int32_t minx = 0x7FFFFFFF;
9216:     int32_t miny = 0x7FFFFFFF;
9217:     int32_t maxx = -0x7FFFFFFF;
9218:     int32_t maxy = -0x7FFFFFFF;
9219:     int i;
9220: 
9221:     for (i = 0; i < 2; i++) {
9222:         int x;
9223:         int y;
9224: 
9225:         helm_ring_pt(edges[i], r_in, &x, &y);
9226:         minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
9227:         miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
9228:         helm_ring_pt(edges[i], r_out, &x, &y);
9229:         minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
9230:         miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
9231:     }
9232:     /* 指针杆 + 横杆两端（横杆 11px ≈ 在 r=96 上 ±7°）。 */
9233:     {
9234:         static const int pa[2] = { -7, 7 };
9235:         int x;
9236:         int y;
9237: 
9238:         helm_ring_pt(angle, HELM_RING_PTR_R0, &x, &y);
9239:         minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
9240:         miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
9241:         for (i = 0; i < 2; i++) {
9242:             helm_ring_pt(angle + pa[i], HELM_RING_PTR_R1, &x, &y);
9243:             minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
9244:             miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
9245:         }
9246:     }
9247: 
9248:     a->x1 = (int32_t)minx - 4;
9249:     a->y1 = (int32_t)miny - 4;
9250:     a->x2 = (int32_t)maxx + 4;
9251:     a->y2 = (int32_t)maxy + 4;
9252: }
