90:  * 本地原来是 `#if !LV_USE_SIFLI_EPIC_DRAW_THREAD`（只要有 OS 就注册）—— 当前配置下未开
754: static int32_t _epic_dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)
755: {
756:     lv_draw_sifli_epic_unit_t * draw_epic_unit = (lv_draw_sifli_epic_unit_t *)draw_unit;
757: 
758:     /* Try to get a ready to draw task */
759:     lv_draw_task_t * task = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_SIFLI_EPIC);
760: 
761:     if(task == NULL) {
762:         return LV_DRAW_UNIT_IDLE;
763:     }
764: 
765: #if LV_USE_SIFLI_EPIC_DRAW_THREAD
766:     /* Hand-off queue full: report "busy" so lv_draw_dispatch() waits for the
767:      * completion request instead of spinning on this unit. */
768:     if(_epic_queue_count(draw_epic_unit) >= LV_SIFLI_EPIC_QUEUE_LEN) {
769:         return 0;
770:     }
771: #else
772:     /* Return immediately if EPIC is busy */
773:     if(draw_epic_unit->task_act) {
774:         return 0;
775:     }
776: #endif
777: 
778:     /* Let the SW unit draw this task if not preferred for EPIC */
779:     if(task->preferred_draw_unit_id != DRAW_UNIT_ID_SIFLI_EPIC) {
780:         return LV_DRAW_UNIT_IDLE;
781:     }
782: 
783:     /* Allocate buffer for layer */
784:     if(lv_draw_layer_alloc_buf(layer) == NULL) {
785:         EPIC_ASSERT_MSG(false, "EPIC: Failed to allocate layer draw buffer");
786:         return LV_DRAW_UNIT_IDLE;
787:     }
788: 
789: #if LV_USE_SIFLI_EPIC_DRAW_THREAD
790:     /* Batch: hand every currently independent EPIC task of this layer to the
791:      * render thread in one go.  lv_draw_get_next_available_task() only returns
792:      * non-overlapping WAITING tasks, so this is the same task set repeated
793:      * lv_draw_dispatch() calls would have produced, minus the wakeup per task. */
794:     int32_t taken = 0;
795:     while(task != NULL &&
796:           _epic_queue_count(draw_epic_unit) < LV_SIFLI_EPIC_QUEUE_LEN) {
797:         if(task->preferred_draw_unit_id != DRAW_UNIT_ID_SIFLI_EPIC) {
798:             break;
799:         }
800: 
801:         task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
802:         task->draw_unit = &draw_epic_unit->base_unit;
803: 
804:         if(!_epic_queue_push(draw_epic_unit, task)) {
805:             /* Should not happen (count checked above), but never lose a task:
806:              * put it back to WAITING so a later dispatch can pick it up. */
807:             task->state = LV_DRAW_TASK_STATE_WAITING;
808:             break;
809:         }
810: 
811:         taken++;
812:         task = lv_draw_get_next_available_task(layer, task, DRAW_UNIT_ID_SIFLI_EPIC);
813:     }
814: 
815:     if(epic_dispatch_log_cnt < 8) {
816:         LV_LOG_WARN("EPIC dispatch[%u]: n=%d inited=%d",
817:                     (unsigned int)epic_dispatch_log_cnt,
818:                     (int)taken,
819:                     draw_epic_unit->inited ? 1 : 0);
820:         epic_dispatch_log_cnt++;
821:     }
822: 
823:     /* Let the render thread work (sync is sticky, a queued task cannot be lost) */
824:     if(taken > 0 && draw_epic_unit->inited) {
825:         lv_thread_sync_signal(&draw_epic_unit->sync);
826:     }
827: 
828:     return taken > 0 ? taken : LV_DRAW_UNIT_IDLE;
829: #else
830:     /* Mark task as in progress */
831:     task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
832:     task->draw_unit = &draw_epic_unit->base_unit;
833: 
834:     draw_epic_unit->task_act = task;
835:     /* Execute drawing immediately */
836:     _epic_execute_drawing(draw_epic_unit);
837: 
838:     draw_epic_unit->task_act->state = LV_DRAW_TASK_STATE_FINISHED;
839:     draw_epic_unit->task_act = NULL;
840: 
841:     /* Request new dispatching */
842:     lv_draw_dispatch_request();
